<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Tagihan', href: '/owner/invoices' }, { title: 'Detail', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    let { invoice, idempotency_key }: { invoice: { id: number; invoice_number: string; due_date: string; cycle_start_date: string | null; cycle_end_exclusive: string | null; property: { name: string } | null; room: { code: string } | null; resident: { full_name: string; whatsapp_number: string } | null; total_due_rupiah: number; paid_rupiah: number; balance_rupiah: number; status: string; lines: { id: number; kind: string; description: string; amount_rupiah: number }[]; adjustments: { id: number; kind: string; amount_rupiah: number; reason: string; created_at: string }[]; cash_allocations: { id: number; invoice_number?: string; amount_rupiah: number; occurred_on: string | null; method: string | null; cash_transaction_id: number }[]; deposit_settlements_rupiah: number }; idempotency_key: string } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
</script>

<AppHead title={invoice.invoice_number} />
<main class="mx-auto w-full max-w-5xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">{invoice.property?.name ?? 'Tagihan'}{invoice.room ? ` · Kamar ${invoice.room.code}` : ''}</p><h1 class="text-3xl font-semibold tracking-tight">{invoice.invoice_number}</h1><p class="text-sm text-muted-foreground">{invoice.resident?.full_name ?? '—'} · jatuh tempo {invoice.due_date}</p></div><div class="flex gap-2"><Link href={`/owner/payments/create?invoice_id=${invoice.id}`} class="inline-flex rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Catat pembayaran</Link><Link href="/owner/invoices" class="inline-flex rounded-md border px-4 py-2 text-sm">Daftar tagihan</Link></div></header>
    <section class="grid gap-4 sm:grid-cols-3"><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Total kewajiban</p><p class="mt-2 text-2xl font-semibold">{money(invoice.total_due_rupiah)}</p></article><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Sudah dibayar / diselesaikan</p><p class="mt-2 text-2xl font-semibold">{money(invoice.paid_rupiah)}</p></article><article class="rounded-xl border bg-card p-5"><p class="text-sm text-muted-foreground">Sisa</p><p class="mt-2 text-2xl font-semibold">{money(invoice.balance_rupiah)}</p><p class="mt-1 text-xs text-muted-foreground">Status: {invoice.status}</p></article></section>
    <section class="grid gap-4 lg:grid-cols-2"><article class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Rincian tagihan</h2><div class="mt-3 divide-y">{#each invoice.lines as line (line.id)}<div class="flex justify-between gap-4 py-3 text-sm"><div><p class="font-medium">{line.description}</p><p class="text-xs text-muted-foreground">{line.kind}</p></div><p>{money(line.amount_rupiah)}</p></div>{/each}{#each invoice.adjustments as adjustment (adjustment.id)}<div class="flex justify-between gap-4 py-3 text-sm"><div><p class="font-medium">Penyesuaian {adjustment.kind === 'credit' ? 'kredit' : 'debit'}</p><p class="text-xs text-muted-foreground">{adjustment.reason}</p></div><p>{adjustment.kind === 'credit' ? '−' : '+'}{money(adjustment.amount_rupiah)}</p></div>{/each}</div></article><article class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Pembayaran dan settlement</h2>{#if invoice.cash_allocations.length === 0 && invoice.deposit_settlements_rupiah === 0}<p class="mt-3 text-sm text-muted-foreground">Belum ada pembayaran.</p>{:else}<div class="mt-3 divide-y">{#each invoice.cash_allocations as allocation (allocation.id)}<Link href={`/owner/payments/${allocation.cash_transaction_id}`} class="flex justify-between gap-4 py-3 text-sm hover:text-primary"><span>{allocation.occurred_on} · {allocation.method ?? 'Transfer'} · Penerimaan kas</span><span>{money(allocation.amount_rupiah)}</span></Link>{/each}{#if invoice.deposit_settlements_rupiah > 0}<div class="flex justify-between py-3 text-sm"><span>Settlement nonkas dari deposit</span><span>{money(invoice.deposit_settlements_rupiah)}</span></div>{/if}</div>{/if}</article></section>
    <section class="space-y-4 rounded-xl border bg-card p-5"><div><h2 class="font-semibold">Penyesuaian invoice</h2><p class="mt-1 text-sm text-muted-foreground">Catat koreksi sebagai entri baru; invoice dan pembayaran historis tetap tersimpan.</p></div><Form action={`/owner/invoices/${invoice.id}/adjustments`} method="post" class="grid gap-4 sm:grid-cols-2">{#snippet children({ errors, processing })}<input type="hidden" name="idempotency_key" value={idempotency_key} /><div class="space-y-2"><label for="kind" class="text-sm font-medium">Jenis</label><select id="kind" name="kind" required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="credit">Kredit / pengurang</option><option value="debit">Debit / penambah</option></select><InputError message={errors.kind} /></div><div class="space-y-2"><label for="amount_rupiah" class="text-sm font-medium">Nominal (Rupiah)</label><Input id="amount_rupiah" name="amount_rupiah" type="number" min={1} step={1} required /><InputError message={errors.amount_rupiah} /></div><div class="space-y-2 sm:col-span-2"><label for="reason" class="text-sm font-medium">Alasan</label><textarea id="reason" name="reason" required minlength="3" maxlength="1000" rows={2} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.reason} /></div><InputError message={errors.adjustment} /><div class="sm:col-span-2 flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Menyimpan…' : 'Simpan penyesuaian'}</Button></div>{/snippet}</Form></section>
</main>
